<script setup lang="ts">
import {ref} from 'vue'; import {useRoute,useRouter} from 'vue-router'; import {BookOpen,Eye,EyeOff} from 'lucide-vue-next'; import {useAuthStore} from '../stores/authStore';
const email=ref(''),password=ref(''),show=ref(false),error=ref('');const auth=useAuthStore(),route=useRoute(),router=useRouter();
async function submit(){error.value='';try{await auth.login(email.value,password.value);const target=typeof route.query.redirect==='string'?route.query.redirect:'/dashboard';await router.push(target);}catch(e){const response=(e as {response?:{data?:{message?:string}}}).response;error.value=response?.data?.message??'Không thể đăng nhập. Vui lòng kiểm tra lại thông tin.';}}
</script>
<template><main class="grid min-h-screen bg-primary-50 p-4 lg:grid-cols-2"><section class="hidden rounded-3xl bg-ink p-12 text-white lg:flex lg:flex-col"><div class="flex items-center gap-3"><span class="grid size-11 place-items-center rounded-xl bg-primary-500"><BookOpen/></span><b>Hành Trang Đức Tin</b></div><div class="my-auto"><p class="text-blue-200">Giáo xứ An Bình</p><h1 class="mt-3 text-4xl font-bold leading-tight">Đồng hành cùng hành trình đức tin.</h1></div></section><section class="grid place-items-center"><form class="w-full max-w-md rounded-3xl bg-white p-7 shadow-sm sm:p-10" @submit.prevent="submit"><div class="mb-8 lg:hidden"><div class="grid size-11 place-items-center rounded-xl bg-primary-600 text-white"><BookOpen/></div><h1 class="mt-4 text-xl font-bold text-ink">Hành Trang Đức Tin</h1></div><h2 class="text-2xl font-bold text-ink">Đăng nhập</h2><p class="mt-2 text-sm text-slate-500">Chào mừng bạn quay trở lại.</p><p v-if="error" role="alert" class="mt-5 rounded-xl bg-rose-50 p-3 text-sm text-rose-700">{{error}}</p><label class="mt-6 block text-sm font-medium text-slate-700">Email<input v-model="email" type="email" required autocomplete="email" class="mt-2 w-full rounded-xl border border-slate-300 px-3 py-2.5 outline-none focus:border-primary-500" placeholder="name@example.com"></label><label class="mt-5 block text-sm font-medium text-slate-700">Mật khẩu<span class="relative mt-2 block"><input v-model="password" :type="show?'text':'password'" required autocomplete="current-password" class="w-full rounded-xl border border-slate-300 px-3 py-2.5 pr-10 outline-none focus:border-primary-500"><button type="button" class="absolute right-2 top-2 text-slate-500" @click="show=!show"><EyeOff v-if="show" class="size-5"/><Eye v-else class="size-5"/></button></span></label><button :disabled="auth.isSubmitting" class="mt-7 w-full rounded-xl bg-primary-600 py-3 text-sm font-semibold text-white disabled:opacity-60">{{auth.isSubmitting?'Đang đăng nhập…':'Đăng nhập'}}</button><p class="mt-6 text-center text-xs text-slate-500">Tài khoản demo: teacher@giaoly.test · mật khẩu: password</p></form></section></main></template>
